<template>
  <main :class="['traffic-page', { 'is-microapp': microapp }]">
    <section v-if="booting" class="state-panel"><a-spin tip="正在加载流量数据..." /></section>
    <template v-else>
      <a-alert v-if="healthMessage" type="warning" show-icon class="health-alert">{{ healthMessage }}</a-alert>
      <section class="control-panel">
        <div class="control-group">
          <template v-if="isFounder"><span class="control-label">命名空间</span><a-select v-model="namespace" allow-search :filter-option="true" style="width:160px" @change="namespaceChanged"><a-option value="*">全部命名空间</a-option><a-option v-for="item in namespaces" :key="item" :value="item">{{ item }}</a-option></a-select></template>
          <a-range-picker v-model:model-value="timeRange" show-time style="width:330px" :disabled-date="disabledDate" @ok="reload" />
          <a-select v-model="domain" allow-search :filter-option="true" placeholder="全部域名" style="width:190px" @change="reload"><a-option value="">全部域名</a-option><a-option v-for="item in domainOptions" :key="item" :value="item">{{ item }}</a-option></a-select>
          <a-select v-model="workload" allow-search :filter-option="true" placeholder="全部 Apps" style="width:220px" @change="reload"><a-option value="">全部 Apps</a-option><a-option v-for="item in appOptions" :key="item.value" :value="item.value">{{ item.label }}</a-option></a-select>
        </div>
        <a-button :loading="loading" @click="reload"><template #icon><icon-refresh /></template>刷新</a-button>
      </section>
      <section class="card chart-card"><div class="section-heading"><h2>请求趋势</h2><a-radio-group v-model="metric" type="button"><a-radio value="requests">请求数</a-radio><a-radio value="traffic">流量</a-radio><a-radio value="bandwidth">带宽</a-radio><a-radio value="hitRate">状态码占比</a-radio><a-radio value="hits">状态码次数</a-radio></a-radio-group></div><TrafficChart :series="series" :metric="metric" :format="metricFormat" /></section>
      <section class="card"><a-tabs v-model:active-key="activeTab" @change="loadTable"><a-tab-pane key="apps" title="按 Apps" /><a-tab-pane key="domains" title="按域名" /><a-tab-pane key="urls" title="热点 URL" /></a-tabs>
        <div class="summary-grid"><article><span>请求总数</span><strong>{{ number(summary.requests) }}</strong><small>经过 Higress 的 HTTP 请求</small></article><article><span>总流量</span><strong>{{ bytes(totalBytes) }}</strong><small>请求与响应字节之和</small></article><article><span>错误率</span><strong :class="{ danger: Number(summary.error_rate) > .05 }">{{ percent(summary.error_rate) }}</strong><small>HTTP 4xx 与 5xx</small></article><article><span>P95 延迟</span><strong>{{ duration(summary.p95_duration_ms) }}</strong><small>网关端到端耗时</small></article></div>
        <div v-if="activeTab === 'urls'" class="filters"><a-input v-model="filters.keyword" allow-clear placeholder="筛选路径" @press-enter="search" /><a-select v-model="filters.method" allow-clear placeholder="请求方法"><a-option v-for="value in methods" :key="value" :value="value">{{ value }}</a-option></a-select><a-select v-model="filters.status" allow-clear placeholder="状态码"><a-option v-for="value in ['2xx','3xx','4xx','5xx']" :key="value" :value="value">{{ value }}</a-option></a-select><a-select v-model="filters.sort"><a-option value="requests">按请求数</a-option><a-option value="traffic">按流量</a-option><a-option value="errors">按错误数</a-option><a-option value="latency">按 P95 延迟</a-option></a-select><a-button type="primary" @click="search">筛选</a-button></div>
        <a-table :data="rows" :loading="tableLoading" :pagination="false" row-key="rowKey"><template #columns><a-table-column v-if="activeTab === 'apps'" title="App"><template #cell="{ record }"><button class="entity-link" @click="openApp(record)">{{ record.workload_title || record.workload_name }}</button><small>{{ record.workload_name }} · {{ record.workload_kind }} · {{ record.workload_namespace }}</small></template></a-table-column><a-table-column v-if="activeTab !== 'apps'" title="域名" data-index="authority" /><a-table-column v-if="activeTab === 'urls'" title="方法" data-index="method" :width="90" /><a-table-column v-if="activeTab === 'urls'" title="路径" data-index="path" /><a-table-column title="请求数" :width="110"><template #cell="{ record }">{{ number(record.requests) }}</template></a-table-column><a-table-column title="流量" :width="120"><template #cell="{ record }">{{ bytes(Number(record.bytes_received || 0) + Number(record.bytes_sent || 0)) }}</template></a-table-column><a-table-column title="错误率" :width="110"><template #cell="{ record }"><span :class="{ danger: Number(record.error_rate) > .05 }">{{ percent(record.error_rate) }}</span></template></a-table-column><a-table-column title="P95 延迟" :width="115"><template #cell="{ record }">{{ duration(record.p95_duration_ms) }}</template></a-table-column></template></a-table>
        <div class="pagination"><span>URL 已在采集时去除查询参数</span><a-pagination v-model:current="page.current" :page-size="page.pageSize" :total="page.total" @change="loadTable" /></div>
      </section>
      <a-drawer :width="960" :visible="appDetail.show" :footer="false" @cancel="appDetail.show = false"><template #title>{{ appDetail.view === 'urls' ? `${appDetail.pod.pod_name || appDetail.pod.upstream_ip} 关联 URL` : `${appDetail.app.workload_name} 关联 Pod` }}</template><template v-if="appDetail.view === 'pods'"><div class="filters"><a-input v-model="appDetail.search" allow-clear placeholder="按 Pod 名称搜索" @press-enter="searchAppPods" /><a-button type="primary" @click="searchAppPods">搜索</a-button></div><a-table :data="appDetail.rows" :loading="appDetail.loading" :pagination="false" row-key="rowKey"><template #columns><a-table-column title="Pod"><template #cell="{ record }"><button class="entity-link" @click="openPodURLs(record)">{{ record.pod_name || record.upstream_ip }}</button><small>{{ record.upstream_ip }} · {{ record.upstream_service || 'Service 未知' }}</small></template></a-table-column><a-table-column title="请求数"><template #cell="{ record }">{{ number(record.requests) }}</template></a-table-column><a-table-column title="流量"><template #cell="{ record }">{{ bytes(Number(record.bytes_received || 0) + Number(record.bytes_sent || 0)) }}</template></a-table-column></template></a-table><div class="pagination"><span>当前 App 的 Pod 流量</span><a-pagination v-model:current="appDetail.page.current" :page-size="appDetail.page.pageSize" :total="appDetail.page.total" @change="loadAppPods" /></div></template><template v-else><a-button type="text" @click="backToPods">返回 Pod</a-button><a-table :data="appDetail.urlRows" :loading="appDetail.loading" :pagination="false" row-key="rowKey"><template #columns><a-table-column title="域名" data-index="authority" /><a-table-column title="方法" data-index="method" :width="90" /><a-table-column title="路径" data-index="path" /><a-table-column title="请求数"><template #cell="{ record }">{{ number(record.requests) }}</template></a-table-column><a-table-column title="流量"><template #cell="{ record }">{{ bytes(Number(record.bytes_received || 0) + Number(record.bytes_sent || 0)) }}</template></a-table-column></template></a-table><div class="pagination"><span>按当前查询条件聚合</span><a-pagination v-model:current="appDetail.urlPage.current" :page-size="appDetail.urlPage.pageSize" :total="appDetail.urlPage.total" @change="loadPodURLs" /></div></template></a-drawer>
    </template>
  </main>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue'
import dayjs from 'dayjs'
import { Message } from '@arco-design/web-vue'
import TrafficChart from './components/TrafficChart.vue'
import { trafficApi } from './api'
import { isMicroapp, userRole } from './runtime'

const booting = ref(true), loading = ref(false), tableLoading = ref(false)
const microapp = isMicroapp()
const health = ref({}), summary = ref({}), series = ref([]), rows = ref([]), namespaces = ref([]), domainOptions = ref([]), appOptions = ref([])
const isFounder = computed(() => userRole() === 'founder')
const namespace = ref('default'), domain = ref(''), workload = ref(''), activeTab = ref('apps'), metric = ref('requests')
const end = dayjs(); const timeRange = ref([end.subtract(1, 'hour').toDate(), end.toDate()])
const page = ref({ current: 1, pageSize: 20, total: 0 }), filters = ref({ keyword: '', method: '', status: '', sort: 'requests' }), methods = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE']
const appDetail = ref({ show: false, view: 'pods', app: {}, pod: {}, search: '', rows: [], urlRows: [], loading: false, page: { current: 1, pageSize: 20, total: 0 }, urlPage: { current: 1, pageSize: 20, total: 0 } })
const totalBytes = computed(() => Number(summary.value.bytes_received || 0) + Number(summary.value.bytes_sent || 0))
const healthMessage = computed(() => health.value?.logs && !health.value.logs.available ? (health.value.logs.message || 'Higress 访问日志不可用') : '')
const params = (extra = {}) => { const [workloadKind = '', workloadName = ''] = workload.value.split(':', 2); return { namespace: namespace.value, start: dayjs(timeRange.value[0]).toISOString(), end: dayjs(timeRange.value[1]).toISOString(), domain: domain.value, workloadKind, workloadName, page: page.value.current, pageSize: page.value.pageSize, step: '5m', ...extra } }
const unwrapList = value => Array.isArray(value) ? value : (value?.items || [])
function number(value) { return Number(value || 0).toLocaleString('zh-CN', { maximumFractionDigits: 0 }) }
function bytes(value) { const n = Number(value || 0); if (n < 1024) return `${n.toFixed(0)} B`; if (n < 1048576) return `${(n / 1024).toFixed(1)} KB`; if (n < 1073741824) return `${(n / 1048576).toFixed(1)} MB`; return `${(n / 1073741824).toFixed(2)} GB` }
function percent(value) { return `${(Number(value || 0) * 100).toFixed(2)}%` }; function duration(value) { const n = Number(value || 0); return n >= 1000 ? `${(n / 1000).toFixed(2)}s` : `${n.toFixed(0)}ms` }
function metricFormat(value) { return metric.value === 'traffic' ? bytes(value) : metric.value === 'bandwidth' ? `${number(value)} bps` : metric.value === 'hitRate' ? percent(value) : number(value) }
function disabledDate(current) { return dayjs(current).isAfter(dayjs(), 'day') || dayjs(current).isBefore(dayjs().subtract(30, 'day'), 'day') }
async function loadOptions() { const [domains, apps] = await Promise.all([trafficApi.domains(params({ domain: undefined, page: 1, pageSize: 100 })), trafficApi.apps(params({ workloadName: undefined, workloadKind: undefined, page: 1, pageSize: 100 }))]); domainOptions.value = unwrapList(domains.list || domains).map(item => item.authority).filter(Boolean); appOptions.value = unwrapList(apps.list || apps).map(item => ({ value: `${item.workload_kind}:${item.workload_name}`, label: `${item.workload_title || item.workload_name} (${item.workload_name})` })).filter(item => item.value !== ':') }
async function loadTable() { tableLoading.value = true; try { const data = await trafficApi[activeTab.value](params(activeTab.value === 'urls' ? filters.value : {})); rows.value = (data.list || []).map((item, index) => ({ ...item, rowKey: `${activeTab.value}-${page.value.current}-${index}` })); page.value.total = Number(data.total || 0) } catch (error) { rows.value = []; page.value.total = 0; Message.error(error.message || '读取列表失败') } finally { tableLoading.value = false } }
async function reload() { if (!timeRange.value?.[0] || !timeRange.value?.[1] || !dayjs(timeRange.value[0]).isBefore(timeRange.value[1])) return Message.error('请选择有效的查询时间'); loading.value = true; page.value.current = 1; try { const [nextHealth, nextSummary, nextSeries] = await Promise.all([trafficApi.health(), trafficApi.summary(params()), trafficApi.series(params())]); health.value = nextHealth || {}; summary.value = nextSummary || {}; series.value = Array.isArray(nextSeries) ? nextSeries : []; await Promise.all([loadTable(), loadOptions()]) } catch (error) { Message.error(error.message || '读取流量数据失败') } finally { loading.value = false } }
function search() { page.value.current = 1; loadTable() }; function namespaceChanged() { domain.value = ''; workload.value = ''; reload() }
function appParams(extra = {}) { return params({ workloadKind: appDetail.value.app.workload_kind, workloadName: appDetail.value.app.workload_name, ...extra }) }
function openApp(record) { appDetail.value = { ...appDetail.value, show: true, view: 'pods', app: record, pod: {}, search: '', rows: [], page: { current: 1, pageSize: 20, total: 0 } }; loadAppPods() }
async function loadAppPods() { appDetail.value.loading = true; try { const data = await trafficApi.pods(appParams({ search: appDetail.value.search, page: appDetail.value.page.current, pageSize: appDetail.value.page.pageSize })); appDetail.value.rows = (data.list || []).map((item, index) => ({ ...item, rowKey: `app-pod-${appDetail.value.page.current}-${index}` })); appDetail.value.page.total = Number(data.total || 0) } catch (error) { appDetail.value.rows = []; appDetail.value.page.total = 0; Message.error(error.message || '读取 Pod 列表失败') } finally { appDetail.value.loading = false } }
function searchAppPods() { appDetail.value.page.current = 1; loadAppPods() }
function openPodURLs(record) { appDetail.value.view = 'urls'; appDetail.value.pod = record; appDetail.value.urlRows = []; appDetail.value.urlPage = { current: 1, pageSize: 20, total: 0 }; loadPodURLs() }
async function loadPodURLs() { appDetail.value.loading = true; try { const data = await trafficApi.urls(appParams({ upstreamIp: appDetail.value.pod.upstream_ip, page: appDetail.value.urlPage.current, pageSize: appDetail.value.urlPage.pageSize, sort: 'requests' })); appDetail.value.urlRows = (data.list || []).map((item, index) => ({ ...item, rowKey: `app-pod-url-${appDetail.value.urlPage.current}-${index}` })); appDetail.value.urlPage.total = Number(data.total || 0) } catch (error) { appDetail.value.urlRows = []; appDetail.value.urlPage.total = 0; Message.error(error.message || '读取 Pod URL 失败') } finally { appDetail.value.loading = false } }
function backToPods() { appDetail.value.view = 'pods'; appDetail.value.pod = {} }
onMounted(async () => { try { if (isFounder.value) { const data = await trafficApi.namespaces(); namespaces.value = unwrapList(data).map(item => item?.metadata?.name).filter(Boolean); namespace.value = namespaces.value.includes('default') ? 'default' : (namespaces.value[0] || 'default') } try { health.value = await trafficApi.health() || {} } catch (error) { health.value = { logs: { available: false, message: error.message } } } await reload() } catch (error) { Message.error(error.message || '加载流量数据失败') } finally { booting.value = false } })
</script>
